// function encrypt(char) mein single character do
// A->Z, B->Y, C->X ... Z->A (reverse alphabet)
// Non-letter: same return karo

solution:
function encrypt(char) {
  const lower = char.toLowerCase()
  if (lower >= "a" && lower <= "z") {
    const code = lower.charCodeAt(0)
    const encrypted = String.fromCharCode(122 - code + 97)
    return char === char.toUpperCase() ? encrypted.toUpperCase() : encrypted
  }
  return char
}
